INSERT INTO iam_role_permission (
    tenant_id, role_id, permission_id, created_by, updated_by
)
SELECT #{tenantId}, #{roleId}, #{permissionId}, #{operator}, #{operator}
WHERE NOT EXISTS (
    SELECT 1
    FROM iam_role_permission existing
    WHERE existing.tenant_id = #{tenantId}
      AND existing.role_id = #{roleId}
      AND existing.permission_id = #{permissionId}
      AND existing.deleted_at IS NULL
)

INSERT INTO iam_user_role (
    tenant_id, user_id, role_id, created_by, updated_by
)
SELECT #{tenantId}, #{userId}, #{roleId}, #{operator}, #{operator}
WHERE NOT EXISTS (
    SELECT 1
    FROM iam_user_role existing
    WHERE existing.tenant_id = #{tenantId}
      AND existing.user_id = #{userId}
      AND existing.role_id = #{roleId}
      AND existing.deleted_at IS NULL
)
